package io.fireflysoftware.common.config.core.authority;

import io.fireflysoftware.common.config.core.authority.impl.TenantResourceBindingRecoveryReaderImpl;
import io.fireflysoftware.common.config.interfaces.authority.*;
import io.fireflysoftware.common.config.interfaces.authority.TenantResourceBindingContracts.*;
import io.fireflysoftware.common.config.interfaces.authority.TenantResourceBindingGovernedContracts.*;
import io.fireflysoftware.common.config.models.entities.authority.*;
import io.fireflysoftware.common.config.models.repositories.authority.*;
import com.fasterxml.jackson.databind.json.JsonMapper;
import io.r2dbc.postgresql.codec.Json;
import org.junit.jupiter.api.Test;
import org.springframework.data.r2dbc.core.R2dbcEntityOperations;
import org.springframework.r2dbc.core.DatabaseClient;
import org.springframework.r2dbc.connection.R2dbcTransactionManager;
import reactor.core.publisher.Mono;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class TenantResourceBindingRecoveryReaderTest {
    static final class Fixture {
        final TenantResourceBindingServiceTest.Fixture owner=new TenantResourceBindingServiceTest.Fixture();
        final NativeActionRepository actions=mock(NativeActionRepository.class);
        final NativeReceiptRepository receipts=mock(NativeReceiptRepository.class);
        final NativeAuthorityOperationsRepository nativeReads=mock(NativeAuthorityOperationsRepository.class);
        final Intent intent=new Intent(Kind.CONTROL,null,null,TenantResourceBindingServiceTest.command(Operation.TENANT_RESOURCE_BINDING_ESTABLISH,0));
        final ActionRequest request=new ActionRequest(intent,TenantResourceBindingGovernedCodec.digest(intent));
        final TenantResourceBindingRecoveryReader service;
        final InstitutionAuthorityTransaction transactions;
        Fixture(){var db=mock(DatabaseClient.class);when(db.getConnectionFactory()).thenReturn(owner.factory);var operations=mock(R2dbcEntityOperations.class);when(operations.getDatabaseClient()).thenReturn(db);when(nativeReads.environment("READ_ACTION")).thenReturn(Mono.just(true));when(nativeReads.establishContext(any(),isNull(),eq("READ_ACTION"),eq("ACTION"),any(),any(),anyString(),anyString(),anyString(),anyString(),any(),any(),isNull(),eq(true),anyLong(),anyLong())).thenAnswer(call->owner.owned().thenReturn(true));transactions=new InstitutionAuthorityTransaction(new R2dbcTransactionManager(owner.factory),operations,new InstitutionAuthorityDatabaseContext(operations,nativeReads));service=new TenantResourceBindingRecoveryReaderImpl(owner.governance,transactions,actions,receipts);when(actions.findByIdTenantIdAndIdActionId(any(),any())).thenAnswer(call->owner.owned().then(Mono.empty()));clearInvocations(owner.store,owner.nativeAuthority);}
        ActionRow row(String employee,String client){var command=intent.control();return new ActionRow(new ActionKey(TenantResourceBindingServiceTest.T,command.actionId()),command.operation().name(),command.definition().bindingId(),command.proposalId(),1L,"retained-original-native-request".getBytes(java.nio.charset.StandardCharsets.UTF_8),TenantResourceBindingGovernedCodec.canonical(intent),request.originalIntentDigest(),InstitutionAuthorityBudgetTest.NOW.minusSeconds(30).toEpochMilli(),"STAFF",InstitutionAuthorityBudgetTest.I,"actual-subject",UUID.fromString(employee),client,"APPLIED",Json.of("{\"reference\":{\"bindingId\":\""+command.definition().bindingId()+"\",\"version\":1,\"definitionDigest\":\""+TenantResourceBindingCodec.definitionDigest(command.definition())+"\"},\"controlVersion\":1,\"state\":\"ACTIVE\"}"),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),OffsetDateTime.ofInstant(InstitutionAuthorityBudgetTest.NOW.minusSeconds(60),ZoneOffset.UTC));}
        ReceiptRow receipt(ActionRow row,String actorTenant)throws Exception{var json=JsonMapper.builder().build();var body=json.createObjectNode();body.put("encoding","FF_NATIVE_INSTITUTION_RECEIPT_JSON_V1");body.put("tenantId",row.id().tenantId().toString());body.put("actionId",row.id().actionId().toString());body.put("operation",row.operation());body.put("resourceId",row.resourceId().toString());body.put("proposalId",row.proposalId().toString());body.put("proposalRevision",row.proposalRevision());body.put("originalBase64",Base64.getEncoder().encodeToString(row.originalRequest()));body.put("canonicalIntent",row.canonicalIntent());body.put("intentDigest",row.intentDigest());body.put("deadlineEpochMillis",row.deadlineEpochMillis());body.put("resultKind",row.resultKind());body.set("result",json.readTree(row.result().asString()));body.set("actor",json.valueToTree(new NativeAuthorityActor(row.actorKind(),row.actorIssuer(),row.actorSubject(),actorTenant,row.actorEmployeeId().toString(),row.actorClientId())));body.put("acceptedAtEpochMillis",row.admittedAt().toInstant().toEpochMilli());body.put("receiptId",row.receiptId().toString());body.put("auditId",row.auditId().toString());body.put("eventId",row.eventId().toString());String canonical=json.writeValueAsString(body);return new ReceiptRow(row.id(),row.receiptId(),Json.of(canonical),canonical,AuthorityWire.sha(canonical));}
        void retain(ActionRow row,String actorTenant)throws Exception{when(actions.findByIdTenantIdAndIdActionId(any(),any())).thenAnswer(call->owner.owned().thenReturn(row));when(receipts.findByIdTenantIdAndIdActionId(any(),any())).thenAnswer(call->owner.owned().thenReturn(receipt(row,actorTenant)));}
    }
    @Test void aFreshReaderRecoversOriginalHistoricalReceiptAfterItsBusinessDeadlineWithoutWriting()throws Exception{var f=new Fixture();var row=f.row(InstitutionAuthorityBudgetTest.E,null);f.retain(row,InstitutionAuthorityBudgetTest.T);var result=f.service.recover(f.request,f.owner.budget()).block();assertEquals(RecoveryStatus.FOUND,result.status());assertEquals(row.id().actionId(),result.actionId());assertEquals(f.request.originalIntentDigest(),result.intentDigest());assertTrue(result.snapshot().historicalOnly());assertEquals(1,f.owner.commits.get());verify(f.actions,times(1)).findByIdTenantIdAndIdActionId(TenantResourceBindingServiceTest.T,row.id().actionId());verify(f.receipts,times(1)).findByIdTenantIdAndIdActionId(TenantResourceBindingServiceTest.T,row.id().actionId());verifyNoInteractions(f.owner.store,f.owner.nativeAuthority);verify(f.nativeReads).environment("READ_ACTION");verify(f.nativeReads).establishContext(any(),isNull(),eq("READ_ACTION"),eq("ACTION"),eq(row.id().actionId()),eq(row.id().actionId()),anyString(),eq("STAFF"),eq(InstitutionAuthorityBudgetTest.I),eq("actual-subject"),eq(TenantResourceBindingServiceTest.T),eq(UUID.fromString(InstitutionAuthorityBudgetTest.E)),isNull(),eq(true),anyLong(),anyLong());verifyNoMoreInteractions(f.nativeReads);}
    @Test void absenceAtThisReadDoesNotCreateAReplacementAction(){var f=new Fixture();var result=f.service.recover(f.request,f.owner.budget()).block();assertEquals(RecoveryStatus.NOT_OBSERVED_AT_THIS_READ,result.status());assertNull(result.snapshot());verifyNoInteractions(f.receipts,f.owner.store,f.owner.nativeAuthority);}
    @Test void differentRetainedStaffIsDeniedBeforeReadingAnyReceiptOrReturningConflict()throws Exception{var f=new Fixture();f.retain(f.row("00000000-0000-0000-0000-000000000099",null),InstitutionAuthorityBudgetTest.T);assertThrows(Exception.class,()->f.service.recover(f.request,f.owner.budget()).block());verifyNoInteractions(f.receipts);assertEquals(0,f.owner.commits.get());assertEquals(1,f.owner.rollbacks.get());}
    @Test void aDifferentRetainedRegisteredClientCannotBorrowTheOriginalReceipt()throws Exception{var f=new Fixture();f.retain(f.row(InstitutionAuthorityBudgetTest.E,"different-client"),InstitutionAuthorityBudgetTest.T);assertThrows(Exception.class,()->f.service.recover(f.request,f.owner.budget()).block());verifyNoInteractions(f.receipts);}
    @Test void aReceiptFromAnotherCanonicalPlatformTenantIsDenied()throws Exception{var f=new Fixture();f.retain(f.row(InstitutionAuthorityBudgetTest.E,null),"00000000-0000-0000-0000-000000000088");assertThrows(Exception.class,()->f.service.recover(f.request,f.owner.budget()).block());assertEquals(0,f.owner.commits.get());assertEquals(1,f.owner.rollbacks.get());}
    @Test void anAuthorizedOriginalActorSeesConflictWithoutAnotherActionsReceipt()throws Exception{var f=new Fixture();var row=f.row(InstitutionAuthorityBudgetTest.E,null);var c=f.intent.control();var different=new Command(c.actionId(),c.proposalId(),c.operation(),c.definition(),c.expectedCurrentEligibility(),1);String canonical=TenantResourceBindingCodec.commandCanonical(different);var changed=new ActionRow(row.id(),row.operation(),row.resourceId(),row.proposalId(),row.proposalRevision(),row.originalRequest(),canonical,TenantResourceBindingCodec.commandDigest(different),row.deadlineEpochMillis(),row.actorKind(),row.actorIssuer(),row.actorSubject(),row.actorEmployeeId(),row.actorClientId(),row.resultKind(),row.result(),row.receiptId(),row.auditId(),row.eventId(),row.admittedAt());f.retain(changed,InstitutionAuthorityBudgetTest.T);var result=f.service.recover(f.request,f.owner.budget()).block();assertEquals(RecoveryStatus.INTENT_CONFLICT,result.status());assertNull(result.snapshot());assertEquals(f.request.originalIntentDigest(),result.intentDigest());verifyNoInteractions(f.owner.store,f.owner.nativeAuthority);}
    @Test void originalBudgetExpiresBeforeAnyReadContextIsAcquired(){var f=new Fixture();var budget=f.owner.budget();var call=f.service.recover(f.request,budget);f.owner.time.advance(800);assertThrows(Exception.class,call::block);verifyNoInteractions(f.actions,f.receipts,f.nativeReads);}
    @Test void finalCurrentAuthorityStallIsBoundedOnTheDirectServicePathWithoutAnyWebFilter(){var f=new Fixture();var calls=new java.util.concurrent.atomic.AtomicInteger();var authority=new InstitutionAuthorityAuthorization(()->Mono.just(InstitutionAuthorityBudgetTest.principal(InstitutionAuthorityBudgetTest.T)),(p,a,r,c)->calls.incrementAndGet()==4?Mono.never():Mono.just(org.fireflyframework.security.api.domain.Decision.permit()),f.owner.time,Set.of(InstitutionAuthorityBudgetTest.I),InstitutionAuthorityBudgetTest.T,true);var reader=new TenantResourceBindingRecoveryReaderImpl(authority,f.transactions,f.actions,f.receipts);reactor.test.StepVerifier.withVirtualTime(()->reader.recover(f.request,f.owner.budget())).thenAwait(java.time.Duration.ofMillis(801)).expectError(java.util.concurrent.TimeoutException.class).verify();assertEquals(4,calls.get());verifyNoInteractions(f.owner.store,f.owner.nativeAuthority);}
    @Test void revokedCurrentPolicyCannotReadAnOriginalReceipt(){var f=new Fixture();f.owner.allowed.set(false);assertThrows(Exception.class,()->f.service.recover(f.request,f.owner.budget()).block());verifyNoInteractions(f.actions,f.receipts,f.nativeReads);}
}
